MAX_REFUNDS_PER_PAYMENT = 3

def create_refund(client, payment, amount, key):
    if key in client.used_keys:
        return client.used_keys[key]
    if amount > payment.captured:
        return Response(422, {"code": "AMOUNT_EXCEEDS_CAPTURE"})
    if len(payment.refunds) >= MAX_REFUNDS_PER_PAYMENT:
        return Response(409, {"code": "TOO_MANY_REFUNDS"})
    return Response(201, {"id": payment.add_refund(amount).id})

