def test_refund_created(client, payment):
    assert create_refund(client, payment, 10, "k1").status == 201


def test_refund_over_capture_rejected(client, payment):
    assert create_refund(client, payment, 999, "k2").body["code"] == "AMOUNT_EXCEEDS_CAPTURE"


def test_fourth_refund_is_rejected(client, payment_with_three_refunds):
    assert create_refund(client, payment_with_three_refunds, 1, "k3").status == 409


def test_refund_created_again(client, payment):
    assert create_refund(client, payment, 10, "k4").status == 201


